import{_ as i,a,c as e,b as t}from"./chunks/framework.b9WMfGr4.js";const u=JSON.parse('{"title":"2026-03-数学建模竞赛经验与备赛指南","description":"","frontmatter":{"title":"2026-03-数学建模竞赛经验与备赛指南","create-time":"2025-03-11T00:00:00.000Z","update-time":"2026-09-24T00:00:00.000Z","tags":["数学建模","竞赛备赛","感言"]},"headers":[],"relativePath":"posts/经验分享/2026-03-数学建模竞赛经验与备赛指南.md","filePath":"posts/经验分享/2026-03-数学建模竞赛经验与备赛指南.md"}'),s={name:"posts/经验分享/2026-03-数学建模竞赛经验与备赛指南.md"};function r(n,l,o,h,c,d){return a(),e("div",null,[...l[0]||(l[0]=[t(`<h2 id="数学建模竞赛经验与备赛指南" tabindex="-1">数学建模竞赛经验与备赛指南 <a class="header-anchor" href="#数学建模竞赛经验与备赛指南" aria-label="Permalink to &quot;数学建模竞赛经验与备赛指南&quot;">​</a></h2><h3 id="一、先理解数学建模到底在做什么" tabindex="-1">一、先理解数学建模到底在做什么 <a class="header-anchor" href="#一、先理解数学建模到底在做什么" aria-label="Permalink to &quot;一、先理解数学建模到底在做什么&quot;">​</a></h3><p>数学建模的最终目的不是展示复杂公式，而是解决现实问题。面对一个真实背景，需要完成从问题理解、数学抽象、模型求解、结果验证到决策解释的完整闭环。</p><p>评价一个方案时，首先要看它是否真正回答了题目、是否符合实际约束，以及结果能否被解释和验证。模型复杂并不等于模型优秀；简单模型如果适配问题、论证充分、结果稳定，同样可能比复杂模型更有效。</p><h4 id="数学建模与纯数学的区别" tabindex="-1">数学建模与纯数学的区别 <a class="header-anchor" href="#数学建模与纯数学的区别" aria-label="Permalink to &quot;数学建模与纯数学的区别&quot;">​</a></h4><ul><li>纯数学通常追求严格推导和相对确定的答案。</li><li>数学建模面对开放的现实问题，答案往往不唯一。</li><li>数学建模更关注假设是否合理、数据是否可靠、模型是否适用、结果是否具有实际意义。</li><li>经典模型只是工具，真正重要的是为什么选择它、如何使用它，以及它解决了什么问题。</li></ul><h4 id="美赛与国赛的侧重点" tabindex="-1">美赛与国赛的侧重点 <a class="header-anchor" href="#美赛与国赛的侧重点" aria-label="Permalink to &quot;美赛与国赛的侧重点&quot;">​</a></h4><ul><li><strong>美赛更像完成一篇完整的论证文章</strong>：模型是文章的逻辑骨架，求解结果是论据，图表和实验是证据。需要围绕核心问题讲清一个完整故事。</li><li><strong>国赛更强调问题求解与结果质量</strong>：不仅要有完整过程，也要关注模型结论和题目要求的对应关系。</li><li>“美赛看图、国赛看结果”只能作为粗略提醒，不能理解为只做排版或只给答案。图表得分的根本原因通常是过程展示充分、逻辑容易验证，而不是图本身好看。</li></ul><h3 id="二、赛事特点与常见题型" tabindex="-1">二、赛事特点与常见题型 <a class="header-anchor" href="#二、赛事特点与常见题型" aria-label="Permalink to &quot;二、赛事特点与常见题型&quot;">​</a></h3><h4 id="常见赛事" tabindex="-1">常见赛事 <a class="header-anchor" href="#常见赛事" aria-label="Permalink to &quot;常见赛事&quot;">​</a></h4><table tabindex="0"><thead><tr><th>赛事</th><th>常见特点</th><th>备赛重点</th></tr></thead><tbody><tr><td>全国大学生数学建模竞赛</td><td>优化、机理分析、评价和预测问题较多</td><td>数学抽象、模型求解、结果准确性</td></tr><tr><td>MCM/ICM</td><td>连续、离散、数据、环境和政策问题均可能出现</td><td>英文论文、论证逻辑、可视化、开放问题分析</td></tr><tr><td>MathorCup</td><td>企业实际问题和数据驱动问题较多</td><td>数据清洗、商业逻辑、优化与决策</td></tr><tr><td>数维杯</td><td>题型接近国赛，常见跨学科和数据问题</td><td>快速建模、模型实用性、完整交付</td></tr></tbody></table><h4 id="题型与模型速查" tabindex="-1">题型与模型速查 <a class="header-anchor" href="#题型与模型速查" aria-label="Permalink to &quot;题型与模型速查&quot;">​</a></h4><ol><li><p class="pseudo-heading"><strong>优化类</strong></p><ul><li>典型问题：资源分配、路径规划、任务调度、库存管理、多目标决策。</li><li>常用模型：线性规划、整数规划、非线性规划、多目标规划、动态规划、图论、网络流。</li><li>复杂问题可考虑遗传算法、模拟退火等启发式算法，但要说明为什么需要它。</li></ul></li><li><p class="pseudo-heading"><strong>机理分析类</strong></p><ul><li>典型问题：传热、流体、生态变化、传播过程和物理系统演化。</li><li>常用模型：微分方程、偏微分方程、系统动力学和基于规律的仿真。</li><li>重点是解释变量关系和模型假设，而不是单纯套公式。</li></ul></li><li><p class="pseudo-heading"><strong>评价类</strong></p><ul><li>典型问题：城市发展水平、服务质量、可持续性、企业绩效。</li><li>常用模型：层次分析法、熵权法、模糊综合评价、主成分分析、数据包络分析。</li><li>重点是指标体系、权重来源和评价结果的解释性。</li></ul></li><li><p class="pseudo-heading"><strong>预测类</strong></p><ul><li>典型问题：人口、经济指标、交通流量、能源需求和气象趋势。</li><li>常用模型：回归、指数平滑、ARIMA、灰色预测、神经网络。</li><li>小样本不必强行使用深度学习，应根据数据量、时间结构和解释要求选型。</li></ul></li><li><p class="pseudo-heading"><strong>数据驱动类</strong></p><ul><li>典型问题：分类、聚类、用户画像、信用评分和高维数据分析。</li><li>常用模型：随机森林、支持向量机、K-means、集成学习、降维和特征工程。</li><li>重点是数据质量、特征构造、训练验证划分和泛化能力。</li></ul></li><li><p class="pseudo-heading"><strong>跨学科与政策类</strong></p><ul><li>典型问题：环境治理、教育公平、资源竞争和政策效果。</li><li>常用模型：系统动力学、博弈论、多目标优化和多个模型组合。</li><li>重点是因果逻辑、利益相关者、现实约束和建议的可执行性。</li></ul></li></ol><p>模型选择时不要只问“哪个模型更高级”，而要依次确认：</p><ol><li>题目到底要求什么输出？</li><li>现有数据支持什么分析？</li><li>变量、目标和约束分别是什么？</li><li>模型假设能否在现实背景下成立？</li><li>结果能否检验、解释和复现？</li></ol><h3 id="三、赛前准备" tabindex="-1">三、赛前准备 <a class="header-anchor" href="#三、赛前准备" aria-label="Permalink to &quot;三、赛前准备&quot;">​</a></h3><h4 id="知识与资料准备" tabindex="-1">知识与资料准备 <a class="header-anchor" href="#知识与资料准备" aria-label="Permalink to &quot;知识与资料准备&quot;">​</a></h4><ul><li>了解比赛时间、题目数量、提交要求、评分偏好和常见题型。</li><li>收集历年题目、优秀论文、题目解析和比赛复盘。</li><li>建立常用模型、算法、数据处理和可视化的索引，不必把所有材料背下来。</li><li>准备可靠的数据来源、论文检索渠道、代码案例和图表参考。</li><li>对常用模型至少完成一次从输入数据到结果解释的完整实践。</li></ul><h4 id="工具与模板准备" tabindex="-1">工具与模板准备 <a class="header-anchor" href="#工具与模板准备" aria-label="Permalink to &quot;工具与模板准备&quot;">​</a></h4><ul><li>提前确定论文使用 Word、LaTeX 还是在线协作文档。</li><li>统一资料共享、会议沟通、文件命名和版本管理方式。</li><li>准备论文框架、代码模板、符号表、参考文献格式和图表样式。</li><li>提前安装并测试 Python、MATLAB、Lingo 或其他实际会用到的软件。</li><li>工具不求多，确保比赛时真正会用；非必要且学习成本高的工具不要临时引入。</li></ul><h4 id="完整模拟" tabindex="-1">完整模拟 <a class="header-anchor" href="#完整模拟" aria-label="Permalink to &quot;完整模拟&quot;">​</a></h4><p>赛前至少完成一次限时模拟。即使已经看过往届题目，也应该按正式比赛流程走完选题、建模、编程、论文和提交。很多问题只有真正写代码、画图和整理论文时才会暴露。</p><p>准备时间有限时，应优先做到：</p><ul><li>见过主要题型和常用模型。</li><li>跑通过典型案例。</li><li>熟悉比赛完整流程。</li><li>知道遇到问题去哪里查资料。</li></ul><h3 id="四、比赛中的完整工作流" tabindex="-1">四、比赛中的完整工作流 <a class="header-anchor" href="#四、比赛中的完整工作流" aria-label="Permalink to &quot;四、比赛中的完整工作流&quot;">​</a></h3><h4 id="_1-独立阅读题目" tabindex="-1">1. 独立阅读题目 <a class="header-anchor" href="#_1-独立阅读题目" aria-label="Permalink to &quot;1. 独立阅读题目&quot;">​</a></h4><p>三个人先分别逐字阅读题目，标出：</p><ul><li>背景与核心目标。</li><li>每个小问的输入、输出和约束。</li><li>已知数据、缺失数据和数据类型。</li><li>可能涉及的理论、模型与现实因素。</li><li>题目中容易被忽略的限定词。</li></ul><p>独立思考可以避免所有人过早受到同一个思路引导。先记录变量、数据、模型和特殊情况，再交流和删减。</p><h4 id="_2-讨论并完成选题" tabindex="-1">2. 讨论并完成选题 <a class="header-anchor" href="#_2-讨论并完成选题" aria-label="Permalink to &quot;2. 讨论并完成选题&quot;">​</a></h4><p>选题时同时考虑：</p><ul><li>团队对问题背景的理解程度。</li><li>数据是否可获得、可处理。</li><li>模型和代码是否能在限定时间内落地。</li><li>论文是否容易形成清晰主线。</li><li>风险点和兜底方案是否明确。</li></ul><p>讨论必须形成决策。观点可以充分表达，但不能无限争论。建议确定一名主要负责人；其他成员如果不能用更完整的方案推翻当前方案，就先按已确定方向推进，在结果和证据出现后再调整。</p><h4 id="_3-拆分问题并画出流程" tabindex="-1">3. 拆分问题并画出流程 <a class="header-anchor" href="#_3-拆分问题并画出流程" aria-label="Permalink to &quot;3. 拆分问题并画出流程&quot;">​</a></h4><ul><li>把总问题拆成相互衔接的小问题。</li><li>画出从数据到结论的总体流程图。</li><li>再为每个小问细化输入、处理、模型、输出和验证步骤。</li><li>明确小问之间的数据依赖，避免各自完成后无法拼接。</li><li>完成一个小问的基本闭环后，再推进下一个小问。</li></ul><p>流程图既是团队的任务地图，也是论文问题分析部分的重要材料。</p><h4 id="_4-建模与求解" tabindex="-1">4. 建模与求解 <a class="header-anchor" href="#_4-建模与求解" aria-label="Permalink to &quot;4. 建模与求解&quot;">​</a></h4><ul><li>定义变量、参数、符号、目标函数和约束条件。</li><li>写清模型假设以及假设成立的条件。</li><li>先建立可运行的基线模型，再决定是否引入更复杂的方法。</li><li>代码分小块编写和验证，不要一次性堆出完整程序。</li><li>每个小问都要保存输入、过程结果、最终结果和解释。</li></ul><h4 id="_5-结果验证" tabindex="-1">5. 结果验证 <a class="header-anchor" href="#_5-结果验证" aria-label="Permalink to &quot;5. 结果验证&quot;">​</a></h4><ul><li>检查输出的数量级、边界和现实合理性。</li><li>使用残差、误差指标、交叉验证或对照实验评价模型。</li><li>进行灵敏度分析，观察关键参数变化是否导致结论失稳。</li><li>与基线方案或其他模型比较，而不是只展示单一结果。</li><li>主动说明模型的适用范围、局限和可能的改进方向。</li></ul><h4 id="_6-论文整合与提交" tabindex="-1">6. 论文整合与提交 <a class="header-anchor" href="#_6-论文整合与提交" aria-label="Permalink to &quot;6. 论文整合与提交&quot;">​</a></h4><ul><li>边建模边写论文，不要把所有写作工作拖到最后一天。</li><li>每个结果都要能追溯到数据、代码、图表和参考来源。</li><li>完成格式检查、语法检查、公式检查、引用检查和附件检查。</li><li>保存阶段版本和最终备份，提交前由不同成员交叉检查。</li></ul><h3 id="五、团队分工与协作" tabindex="-1">五、团队分工与协作 <a class="header-anchor" href="#五、团队分工与协作" aria-label="Permalink to &quot;五、团队分工与协作&quot;">​</a></h3><p>常见角色包括建模、编程和论文，但角色不能成为信息隔离的理由。</p><ul><li>建模手通常负责把控主线、变量关系和模型选择，可以兼任队长。</li><li>编程手负责数据处理、模型实现、调试、实验和图表输出。</li><li>论文手负责结构、表达、排版、图表整合和最终交付。</li><li>所有人都应理解题目和核心模型，也都应具备基本的论文编辑能力。</li></ul><h4 id="协作原则" tabindex="-1">协作原则 <a class="header-anchor" href="#协作原则" aria-label="Permalink to &quot;协作原则&quot;">​</a></h4><ul><li>权责清晰，承担角色就承担对应交付责任。</li><li>使用统一的 TODO 清单同步进度、依赖和阻塞问题。</li><li>及时共享代码、结果、网址、截图和阶段性文档。</li><li>所有资料和思路都要亲自查、亲自写、亲自运行，不能只停留在口头讨论。</li><li>对方案进行批判，不对人进行批判；不要把工作分歧带入人际关系。</li><li>减少无意义争论，把讨论集中在证据、成本、风险和交付上。</li></ul><h3 id="六、数据、参数与编程" tabindex="-1">六、数据、参数与编程 <a class="header-anchor" href="#六、数据、参数与编程" aria-label="Permalink to &quot;六、数据、参数与编程&quot;">​</a></h3><h4 id="数据要求" tabindex="-1">数据要求 <a class="header-anchor" href="#数据要求" aria-label="Permalink to &quot;数据要求&quot;">​</a></h4><ul><li>数据来源必须真实、可追溯，优先查找政府、机构、论文和项目官网。</li><li>使用二手文章中的国外数据时，应继续追溯到原始报告。</li><li>记录下载地址、访问日期、字段含义、单位和处理方法。</li><li>没有官方数据的题目风险较高，需要提前评估数据搜集成本。</li></ul><h4 id="参数与调参" tabindex="-1">参数与调参 <a class="header-anchor" href="#参数与调参" aria-label="Permalink to &quot;参数与调参&quot;">​</a></h4><ul><li>不要凭感觉随意确定参数。</li><li>参数应来自数据估计、文献依据、现实规则或可解释的实验结果。</li><li>调参过程需要保留基线、变化范围和评价指标。</li><li>模型成立与不成立的条件都要写清楚。</li></ul><h4 id="python-常用流程" tabindex="-1">Python 常用流程 <a class="header-anchor" href="#python-常用流程" aria-label="Permalink to &quot;Python 常用流程&quot;">​</a></h4><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><button class="collapse-btn" title="折叠代码" aria-label="折叠代码"><svg class="collapse-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></button><span class="lang">Text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>读取数据</span></span>
<span class="line"><span>  → 数据清洗与类型检查</span></span>
<span class="line"><span>  → 缺失值和异常值处理</span></span>
<span class="line"><span>  → 标准化或归一化</span></span>
<span class="line"><span>  → 建模与参数设置</span></span>
<span class="line"><span>  → 结果验证与灵敏度分析</span></span>
<span class="line"><span>  → 可视化</span></span>
<span class="line"><span>  → 导出论文所需数据和图表</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div><div class="code-collapsed-indicator"><span class="code-collapsed-text">已折叠代码，点击展开</span><svg class="expand-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></div></div><p>常用工具：</p><ul><li><a href="https://pandas.pydata.org/" target="_blank" rel="noreferrer">pandas</a>：表格数据读取与处理。</li><li><a href="https://numpy.org/" target="_blank" rel="noreferrer">NumPy</a>：数组和数值计算。</li><li><a href="https://matplotlib.org/stable/gallery/index.html" target="_blank" rel="noreferrer">Matplotlib</a>：数据可视化。</li><li><a href="https://scikit-learn.org/stable/" target="_blank" rel="noreferrer">scikit-learn</a>：机器学习、预处理和模型评价。</li><li><a href="https://www.cvxpy.org/tutorial/index.html" target="_blank" rel="noreferrer">CVXPY</a>：凸优化建模。</li><li><a href="https://docs.scipy.org/doc/scipy/tutorial/optimize.html" target="_blank" rel="noreferrer">SciPy</a>：科学计算与优化。</li></ul><h3 id="七、如何使用-ai-辅助数学建模" tabindex="-1">七、如何使用 AI 辅助数学建模 <a class="header-anchor" href="#七、如何使用-ai-辅助数学建模" aria-label="Permalink to &quot;七、如何使用 AI 辅助数学建模&quot;">​</a></h3><p>AI 可以提高资料整理、思路发散和代码调试效率，但不能替代选手做模型选择和真实性判断。</p><h4 id="适合交给-ai-的工作" tabindex="-1">适合交给 AI 的工作 <a class="header-anchor" href="#适合交给-ai-的工作" aria-label="Permalink to &quot;适合交给 AI 的工作&quot;">​</a></h4><ul><li>提取题目关键信息并拆分小问。</li><li>判断可能的题型，列出候选模型和适用条件。</li><li>补充需要考虑的变量、约束和特殊情况。</li><li>提供代码框架、调试建议和异常排查方向。</li><li>分析数据类型、分布、相关性和可视化方式。</li><li>生成论文提纲、符号表初稿和语言修改建议。</li><li>协助设计残差分析、灵敏度分析和对照实验。</li><li>对阶段结果提出反例、风险和改进意见。</li></ul><h4 id="推荐提问顺序" tabindex="-1">推荐提问顺序 <a class="header-anchor" href="#推荐提问顺序" aria-label="Permalink to &quot;推荐提问顺序&quot;">​</a></h4><ol><li>这道题的核心目标和每个小问分别是什么？</li><li>它属于哪些常见题型？判断依据是什么？</li><li>候选模型有哪些？各自的假设、数据要求和局限是什么？</li><li>在当前背景下还需要考虑哪些现实因素和特殊情况？</li><li>是否存在相似案例、论文或公开数据？</li><li>如何验证模型，什么结果可以推翻当前方案？</li></ol><h4 id="使用边界" tabindex="-1">使用边界 <a class="header-anchor" href="#使用边界" aria-label="Permalink to &quot;使用边界&quot;">​</a></h4><ul><li>先把题目原文、数据说明和已有材料提供给 AI，再讨论细节。</li><li>AI 给出的思路必须由人判断是否满足实际约束。</li><li>AI 产生的公式、代码、数据和参考文献必须逐项验证。</li><li>AI 出现幻觉是常态，语气自信不代表内容正确。</li><li>多个 AI 的意见只能作为候选方案，最终必须由团队做决定。</li><li>直接生成的文本往往带有固定表达特征，应基于真实分析重新组织，不能不加约束地粘贴进论文。</li></ul><h3 id="八、论文写作与表达" tabindex="-1">八、论文写作与表达 <a class="header-anchor" href="#八、论文写作与表达" aria-label="Permalink to &quot;八、论文写作与表达&quot;">​</a></h3><h4 id="用一条主线讲清问题" tabindex="-1">用一条主线讲清问题 <a class="header-anchor" href="#用一条主线讲清问题" aria-label="Permalink to &quot;用一条主线讲清问题&quot;">​</a></h4><p>论文不是模型和图表的堆积。全文应围绕一个清晰主线展开：为什么提出这个问题、如何抽象、为什么选择这个模型、结果说明什么、结论在什么范围内成立。</p><p>推荐结构：</p><ol><li>问题重述与核心目标。</li><li>问题分析与总体流程。</li><li>模型假设、符号和数据处理。</li><li>各小问的模型建立、求解和结果。</li><li>模型检验、灵敏度分析与对比。</li><li>优缺点、适用边界和改进方向。</li><li>结论、建议与实际意义。</li></ol><h4 id="图表与排版" tabindex="-1">图表与排版 <a class="header-anchor" href="#图表与排版" aria-label="Permalink to &quot;图表与排版&quot;">​</a></h4><ul><li>图表用于展示论证过程，不是单纯装饰。</li><li>图中字号可以略小于正文，但必须保证可读性。</li><li>图题、表题、坐标、单位和图例要完整。</li><li>流程图应与实际建模过程一致。</li><li>公式、变量和符号保持统一，避免同一概念反复换名。</li><li>严格检查语法、拼写、引用和 LaTeX 报错。</li></ul><h4 id="参考与复用" tabindex="-1">参考与复用 <a class="header-anchor" href="#参考与复用" aria-label="Permalink to &quot;参考与复用&quot;">​</a></h4><ul><li>可以参考优秀论文和专业人士的思路，但必须理解并适配当前题目。</li><li>保存引用网址、截图、数据文件和代码来源，保证能够溯源。</li><li>论文末尾列出真实使用的参考文献和工具来源。</li><li>代码应按自己的逻辑重新组织并补充必要注释；只修改变量名没有实际意义。</li></ul><h3 id="九、创新与质量控制" tabindex="-1">九、创新与质量控制 <a class="header-anchor" href="#九、创新与质量控制" aria-label="Permalink to &quot;九、创新与质量控制&quot;">​</a></h3><p>创新不一定意味着创造全新模型，可以从以下位置切入：</p><ul><li>从新的角度重新定义变量或目标。</li><li>引入更符合背景的约束和机制。</li><li>将不同领域的方法组合起来。</li><li>在基线模型上增加可解释的改进。</li><li>使用多组对比实验说明改进为什么有效。</li><li>将结果转化为更具体、可执行的决策建议。</li></ul><p>不要为了显得高级而堆叠模型。模型质量应体现在：</p><ul><li>问题与模型匹配。</li><li>假设透明且合理。</li><li>数据可靠且处理规范。</li><li>结果经过检验。</li><li>结论可以解释。</li><li>局限得到诚实说明。</li></ul><h3 id="十、比赛检查清单" tabindex="-1">十、比赛检查清单 <a class="header-anchor" href="#十、比赛检查清单" aria-label="Permalink to &quot;十、比赛检查清单&quot;">​</a></h3><h4 id="赛前" tabindex="-1">赛前 <a class="header-anchor" href="#赛前" aria-label="Permalink to &quot;赛前&quot;">​</a></h4><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 比赛规则、时间和提交要求已经确认。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 团队角色、负责人和决策方式已经明确。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 协作、会议、共享和版本管理工具已经测试。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 常用模型、代码和论文模板可以正常使用。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 数据源、优秀论文和历年题目已经建立索引。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 至少完成一次完整模拟并形成复盘。</li></ul><h4 id="比赛中" tabindex="-1">比赛中 <a class="header-anchor" href="#比赛中" aria-label="Permalink to &quot;比赛中&quot;">​</a></h4><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 三名成员都独立阅读并理解题目。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 选题过程考虑了数据、模型、实现、论文和时间风险。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 总体流程图和小问依赖已经明确。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 每个模型都写清变量、假设、目标和约束。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 数据和参数来源可以追溯。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 代码、结果和图表按阶段保存。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 当前方案有基线、检验和兜底方案。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 团队定时同步 TODO、成果和阻塞问题。</li></ul><h4 id="提交前" tabindex="-1">提交前 <a class="header-anchor" href="#提交前" aria-label="Permalink to &quot;提交前&quot;">​</a></h4><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 每个小问都得到明确回答。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 摘要包含问题、方法、主要结果和结论。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 图表、公式、符号、单位和编号保持一致。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 结果经过合理性、误差和灵敏度检查。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 参考文献、数据和工具来源真实完整。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 附录、代码和最终文件符合提交要求。</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 已保存最终备份，并由不同成员交叉检查。</li></ul><h3 id="十一、后续复盘" tabindex="-1">十一、后续复盘 <a class="header-anchor" href="#十一、后续复盘" aria-label="Permalink to &quot;十一、后续复盘&quot;">​</a></h3><p>比赛结束后，不要只关注获奖结果。应分别复盘：</p><ul><li>选题判断是否合理。</li><li>哪个阶段消耗时间最多。</li><li>哪些争论没有产生有效结果。</li><li>数据、模型、代码和论文分别出现了什么问题。</li><li>哪些工具和模板真正有用。</li><li>哪些经验可以沉淀为下一次直接复用的流程。</li></ul><p>数学建模能力不是靠背模型形成的，而是在一次次完整实践中，逐步建立从现实问题到可信结论的解决能力。</p>`,89)])])}const b=i(s,[["render",r]]);export{u as __pageData,b as default};
